-- FRESH PROJECT ONLY: creates the PromoTrack schema and imports outlet.xlsx.
-- For an existing project, inspect migration history and existing data first.
BEGIN;

-- 20251105000000_initial_schema.sql
-- ====================================================================
-- MIGRATION 1: Initial Schema for Promotion Tracking & To-Do List PWA
-- Version: 20251105000000_initial_schema.sql
-- Note: Prepared for review before execution. Do not execute against production without approval.
-- ====================================================================

-- 1. Enable required extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 2. User Profiles Table (Linked to auth.users)
CREATE TABLE IF NOT EXISTS public.profiles (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  email TEXT NOT NULL UNIQUE,
  full_name TEXT NOT NULL,
  phone TEXT,
  role TEXT NOT NULL CHECK (role IN ('admin', 'sales')),
  avatar_url TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 3. Channels Table
CREATE TABLE IF NOT EXISTS public.channels (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL UNIQUE,
  description TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 4. Sub Channels Table
CREATE TABLE IF NOT EXISTS public.sub_channels (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  channel_id UUID NOT NULL REFERENCES public.channels(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  description TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(channel_id, name)
);

-- 5. Stores Table
CREATE TABLE IF NOT EXISTS public.stores (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  store_code TEXT NOT NULL UNIQUE,
  store_name TEXT NOT NULL,
  channel TEXT NOT NULL,
  sub_channel TEXT NOT NULL,
  assigned_sales_user UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  phone TEXT,
  address TEXT,
  city TEXT DEFAULT 'Vientiane',
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Indexes for Store queries
CREATE INDEX IF NOT EXISTS idx_stores_store_code ON public.stores(store_code);
CREATE INDEX IF NOT EXISTS idx_stores_assigned_sales ON public.stores(assigned_sales_user);
CREATE INDEX IF NOT EXISTS idx_stores_channel ON public.stores(channel);

-- 6. Promotions Table
CREATE TABLE IF NOT EXISTS public.promotions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  promotion_name TEXT NOT NULL,
  description TEXT,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  image_url TEXT,
  image_path TEXT,
  status TEXT NOT NULL CHECK (status IN ('Draft', 'Active', 'Completed', 'Cancelled')) DEFAULT 'Draft',
  created_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT check_promotion_dates CHECK (end_date >= start_date)
);

CREATE INDEX IF NOT EXISTS idx_promotions_status ON public.promotions(status);

-- 7. Promotion Stores (Tracking relationship between Stores and Promotions)
CREATE TABLE IF NOT EXISTS public.promotion_stores (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  store_id UUID NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
  promotion_id UUID NOT NULL REFERENCES public.promotions(id) ON DELETE CASCADE,
  order_status TEXT NOT NULL CHECK (order_status IN ('Not Ordered', 'Follow-up Required', 'Ordered', 'Cancelled')) DEFAULT 'Not Ordered',
  order_date TIMESTAMPTZ,
  order_amount NUMERIC(12, 2) DEFAULT 0.00,
  last_follow_up_date TIMESTAMPTZ,
  next_follow_up_date TIMESTAMPTZ,
  remark TEXT,
  updated_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(store_id, promotion_id)
);

CREATE INDEX IF NOT EXISTS idx_promotion_stores_lookup ON public.promotion_stores(promotion_id, store_id);
CREATE INDEX IF NOT EXISTS idx_promotion_stores_status ON public.promotion_stores(order_status);

-- 8. Follow-up Tasks (To-Do List Module)
CREATE TABLE IF NOT EXISTS public.follow_up_tasks (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  store_id UUID NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
  promotion_id UUID REFERENCES public.promotions(id) ON DELETE SET NULL,
  assigned_user UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  task_title TEXT NOT NULL,
  due_date TIMESTAMPTZ NOT NULL,
  priority TEXT NOT NULL CHECK (priority IN ('Low', 'Medium', 'High')) DEFAULT 'Medium',
  task_status TEXT NOT NULL CHECK (task_status IN ('Pending', 'In Progress', 'Completed', 'Cancelled')) DEFAULT 'Pending',
  remark TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_tasks_assigned_user ON public.follow_up_tasks(assigned_user);
CREATE INDEX IF NOT EXISTS idx_tasks_due_date ON public.follow_up_tasks(due_date);
CREATE INDEX IF NOT EXISTS idx_tasks_status ON public.follow_up_tasks(task_status);

-- 9. Order Status History (Audit Trail)
CREATE TABLE IF NOT EXISTS public.order_status_history (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  promotion_store_id UUID NOT NULL REFERENCES public.promotion_stores(id) ON DELETE CASCADE,
  store_id UUID NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
  promotion_id UUID NOT NULL REFERENCES public.promotions(id) ON DELETE CASCADE,
  old_status TEXT,
  new_status TEXT NOT NULL,
  changed_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_audit_promo_store ON public.order_status_history(promotion_store_id);

-- 10. Automatic updated_at trigger function
CREATE OR REPLACE FUNCTION public.handle_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Attach triggers
CREATE TRIGGER set_profiles_updated_at BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();
CREATE TRIGGER set_stores_updated_at BEFORE UPDATE ON public.stores FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();
CREATE TRIGGER set_promotions_updated_at BEFORE UPDATE ON public.promotions FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();
CREATE TRIGGER set_promotion_stores_updated_at BEFORE UPDATE ON public.promotion_stores FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();
CREATE TRIGGER set_follow_up_tasks_updated_at BEFORE UPDATE ON public.follow_up_tasks FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();


-- 20251105000001_rls_policies.sql
-- ====================================================================
-- MIGRATION 2: Row Level Security (RLS) Policies
-- Version: 20251105000001_rls_policies.sql
-- Note: Prepared for review before execution. Do not execute against production without approval.
-- ====================================================================

-- 1. Helper function: Check if authenticated user is an Admin
CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND role = 'admin'
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER STABLE;

-- 2. Helper function: Check if store is assigned to current user
CREATE OR REPLACE FUNCTION public.is_store_assigned_to_me(p_store_id UUID)
RETURNS BOOLEAN AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.stores
    WHERE id = p_store_id AND assigned_sales_user = auth.uid()
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER STABLE;

-- 3. Enable RLS on all tables
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channels ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sub_channels ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.stores ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.promotions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.promotion_stores ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.follow_up_tasks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.order_status_history ENABLE ROW LEVEL SECURITY;

-- ====================================================================
-- PROFILES POLICIES
-- ====================================================================
-- Users can view their own profile and teammates' basic profiles (for assignments)
CREATE POLICY "profiles_select_policy"
  ON public.profiles FOR SELECT
  TO authenticated
  USING (true);

-- Admin can insert and update profiles
CREATE POLICY "profiles_admin_all"
  ON public.profiles FOR ALL
  TO authenticated
  USING (public.is_admin())
  WITH CHECK (public.is_admin());

-- Users can update non-privileged fields on their own profile (cannot change role)
CREATE POLICY "profiles_update_self_non_role"
  ON public.profiles FOR UPDATE
  TO authenticated
  USING (id = auth.uid())
  WITH CHECK (
    id = auth.uid() AND
    role = (SELECT role FROM public.profiles WHERE id = auth.uid())
  );

-- ====================================================================
-- CHANNELS & SUB CHANNELS POLICIES
-- ====================================================================
CREATE POLICY "channels_read_all"
  ON public.channels FOR SELECT
  TO authenticated
  USING (true);

CREATE POLICY "channels_admin_modify"
  ON public.channels FOR ALL
  TO authenticated
  USING (public.is_admin())
  WITH CHECK (public.is_admin());

CREATE POLICY "sub_channels_read_all"
  ON public.sub_channels FOR SELECT
  TO authenticated
  USING (true);

CREATE POLICY "sub_channels_admin_modify"
  ON public.sub_channels FOR ALL
  TO authenticated
  USING (public.is_admin())
  WITH CHECK (public.is_admin());

-- ====================================================================
-- STORES POLICIES
-- ====================================================================
-- Admin can view all stores; Sales users can only view assigned stores
CREATE POLICY "stores_select_policy"
  ON public.stores FOR SELECT
  TO authenticated
  USING (
    public.is_admin() OR assigned_sales_user = auth.uid()
  );

-- Only Admin can insert new stores
CREATE POLICY "stores_insert_admin_only"
  ON public.stores FOR INSERT
  TO authenticated
  WITH CHECK (public.is_admin());

-- Admin can update any store; Sales users CANNOT change assignments or delete
CREATE POLICY "stores_update_admin_only"
  ON public.stores FOR UPDATE
  TO authenticated
  USING (public.is_admin())
  WITH CHECK (public.is_admin());

-- Only Admin can delete stores
CREATE POLICY "stores_delete_admin_only"
  ON public.stores FOR DELETE
  TO authenticated
  USING (public.is_admin());

-- ====================================================================
-- PROMOTIONS POLICIES
-- ====================================================================
-- Active/Completed promotions can be viewed by all authenticated users
CREATE POLICY "promotions_select_policy"
  ON public.promotions FOR SELECT
  TO authenticated
  USING (
    public.is_admin() OR status IN ('Active', 'Completed')
  );

-- Only Admin can manage promotions
CREATE POLICY "promotions_admin_manage"
  ON public.promotions FOR ALL
  TO authenticated
  USING (public.is_admin())
  WITH CHECK (public.is_admin());

-- ====================================================================
-- PROMOTION STORES POLICIES (Order Tracking)
-- ====================================================================
-- Admin sees all; Sales user only sees participating stores assigned to them
CREATE POLICY "promotion_stores_select_policy"
  ON public.promotion_stores FOR SELECT
  TO authenticated
  USING (
    public.is_admin() OR public.is_store_assigned_to_me(store_id)
  );

-- Admin can assign stores to promotions
CREATE POLICY "promotion_stores_admin_insert"
  ON public.promotion_stores FOR INSERT
  TO authenticated
  WITH CHECK (public.is_admin());

-- Admin can update everything; Sales can update order status, dates, and remarks for their stores
CREATE POLICY "promotion_stores_update_policy"
  ON public.promotion_stores FOR UPDATE
  TO authenticated
  USING (
    public.is_admin() OR public.is_store_assigned_to_me(store_id)
  )
  WITH CHECK (
    public.is_admin() OR (
      public.is_store_assigned_to_me(store_id)
      -- Ensure store_id and promotion_id are not tampered with
      AND store_id = store_id
      AND promotion_id = promotion_id
    )
  );

-- Only Admin can unassign / delete promotion stores
CREATE POLICY "promotion_stores_admin_delete"
  ON public.promotion_stores FOR DELETE
  TO authenticated
  USING (public.is_admin());

-- ====================================================================
-- FOLLOW UP TASKS POLICIES (To-Do List)
-- ====================================================================
-- Admin views all tasks; Sales users view only tasks assigned to them
CREATE POLICY "tasks_select_policy"
  ON public.follow_up_tasks FOR SELECT
  TO authenticated
  USING (
    public.is_admin() OR assigned_user = auth.uid()
  );

-- Users can create tasks for their assigned stores or self
CREATE POLICY "tasks_insert_policy"
  ON public.follow_up_tasks FOR INSERT
  TO authenticated
  WITH CHECK (
    public.is_admin() OR (
      assigned_user = auth.uid() AND public.is_store_assigned_to_me(store_id)
    )
  );

-- Users can update status, remark, and due date of their assigned tasks
CREATE POLICY "tasks_update_policy"
  ON public.follow_up_tasks FOR UPDATE
  TO authenticated
  USING (
    public.is_admin() OR assigned_user = auth.uid()
  )
  WITH CHECK (
    public.is_admin() OR assigned_user = auth.uid()
  );

-- Admin can delete any task; Sales users can only delete tasks assigned to them
CREATE POLICY "tasks_delete_policy"
  ON public.follow_up_tasks FOR DELETE
  TO authenticated
  USING (
    public.is_admin() OR assigned_user = auth.uid()
  );

-- ====================================================================
-- ORDER STATUS HISTORY AUDIT POLICIES
-- ====================================================================
CREATE POLICY "history_select_policy"
  ON public.order_status_history FOR SELECT
  TO authenticated
  USING (
    public.is_admin() OR public.is_store_assigned_to_me(store_id)
  );

CREATE POLICY "history_insert_policy"
  ON public.order_status_history FOR INSERT
  TO authenticated
  WITH CHECK (
    public.is_admin() OR public.is_store_assigned_to_me(store_id)
  );


-- 20251105000002_storage_policies.sql
-- ====================================================================
-- MIGRATION 3: Supabase Storage Bucket & Policies for Promotion Images
-- Version: 20251105000002_storage_policies.sql
-- Note: Prepared for review before execution. Do not execute against production without approval.
-- ====================================================================

-- 1. Create the storage bucket for promotion images if not exists
VALUES (
  'promotion-images',
  'promotion-images',
  true,
  5242880, -- 5 MB in bytes
  ARRAY['image/jpeg', 'image/png', 'image/webp']
)
ON CONFLICT (id) DO UPDATE SET
  public = true,
  file_size_limit = 5242880,
  allowed_mime_types = ARRAY['image/jpeg', 'image/png', 'image/webp'];

-- 2. Storage Policies

-- Anyone authenticated can view promotion images
CREATE POLICY "promotion_images_read_policy"
  ON storage.objects FOR SELECT
  TO authenticated
  USING (bucket_id = 'promotion-images');

-- Only Admins can upload promotion images
CREATE POLICY "promotion_images_insert_admin_only"
  ON storage.objects FOR INSERT
  TO authenticated
  WITH CHECK (
    bucket_id = 'promotion-images' AND
    (
      EXISTS (
        SELECT 1 FROM public.profiles
        WHERE id = auth.uid() AND role = 'admin'
      )
    )
  );

-- Only Admins can update/replace promotion images
CREATE POLICY "promotion_images_update_admin_only"
  ON storage.objects FOR UPDATE
  TO authenticated
  USING (
    bucket_id = 'promotion-images' AND
    (
      EXISTS (
        SELECT 1 FROM public.profiles
        WHERE id = auth.uid() AND role = 'admin'
      )
    )
  );

-- Only Admins can delete promotion images
CREATE POLICY "promotion_images_delete_admin_only"
  ON storage.objects FOR DELETE
  TO authenticated
  USING (
    bucket_id = 'promotion-images' AND
    (
      EXISTS (
        SELECT 1 FROM public.profiles
        WHERE id = auth.uid() AND role = 'admin'
      )
    )
  );


-- 20261107000000_outlet_workbook.sql
-- Schema for the nine columns in outlet.xlsx. This migration does not delete
-- existing rows and does not create or impersonate Supabase Auth users.

CREATE TABLE public.main_channels (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL UNIQUE CHECK (btrim(name) <> '')
);
CREATE TABLE public.mdes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL UNIQUE CHECK (btrim(name) <> '')
);

ALTER TABLE public.channels ADD COLUMN main_channel_id UUID REFERENCES public.main_channels(id) ON DELETE RESTRICT;
ALTER TABLE public.profiles ADD COLUMN mde_id UUID REFERENCES public.mdes(id) ON DELETE SET NULL;
ALTER TABLE public.stores
  ADD COLUMN mde_name TEXT,
  ADD COLUMN main_channel TEXT,
  ADD COLUMN village TEXT,
  ADD COLUMN district TEXT,
  ADD COLUMN province TEXT,
  ADD COLUMN mde_id UUID REFERENCES public.mdes(id) ON DELETE RESTRICT,
  ADD COLUMN main_channel_id UUID REFERENCES public.main_channels(id) ON DELETE RESTRICT,
  ADD COLUMN channel_id UUID REFERENCES public.channels(id) ON DELETE RESTRICT,
  ADD COLUMN sub_channel_id UUID REFERENCES public.sub_channels(id) ON DELETE RESTRICT,
  ALTER COLUMN city DROP DEFAULT;
CREATE INDEX idx_stores_mde ON public.stores(mde_id);
CREATE INDEX idx_stores_district ON public.stores(district);
CREATE INDEX idx_stores_sub_channel ON public.stores(sub_channel_id);

-- MDEs are source business entities, not auth accounts. Link a real authenticated
-- sales profile via profiles.mde_id after the owner provisions the account.
CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin');
$$;
-- Adding an MDE binding also requires freezing it for self-service profile edits;
-- otherwise a Sales user could point their own profile at another MDE's outlets.
CREATE FUNCTION public.can_update_own_profile(profile_id UUID, profile_role TEXT, profile_mde_id UUID)
RETURNS BOOLEAN LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = auth.uid() AND p.id = profile_id
    AND p.role = profile_role AND p.mde_id IS NOT DISTINCT FROM profile_mde_id);
$$;
DROP POLICY IF EXISTS profiles_update_self_non_role ON public.profiles;
CREATE POLICY profiles_update_self_non_role ON public.profiles FOR UPDATE TO authenticated
  USING (id = auth.uid()) WITH CHECK (public.can_update_own_profile(id, role, mde_id));

CREATE OR REPLACE FUNCTION public.is_store_assigned_to_me(p_store_id UUID)
RETURNS BOOLEAN LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.stores s
    WHERE s.id = p_store_id AND (
      s.assigned_sales_user = auth.uid() OR
      s.mde_id IN (SELECT p.mde_id FROM public.profiles p WHERE p.id = auth.uid() AND p.mde_id IS NOT NULL)
    )
  );
$$;
DROP POLICY IF EXISTS stores_select_policy ON public.stores;
CREATE POLICY stores_select_policy ON public.stores FOR SELECT TO authenticated
  USING (public.is_admin() OR public.is_store_assigned_to_me(id));

ALTER TABLE public.main_channels ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mdes ENABLE ROW LEVEL SECURITY;
CREATE POLICY main_channels_read ON public.main_channels FOR SELECT TO authenticated USING (true);
CREATE POLICY main_channels_admin ON public.main_channels FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY mdes_read ON public.mdes FOR SELECT TO authenticated USING (true);
CREATE POLICY mdes_admin ON public.mdes FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

-- Compatibility view preserves the workbook's original header spellings.
-- security_invoker ensures its rows obey the caller's store RLS policies.
CREATE VIEW public.outlet_directory WITH (security_invoker = true) AS
SELECT mde_name AS "MDE NAME", store_code AS "OUTLET CODE", store_name AS "OUTLET",
       main_channel AS "MIAN CHANEL", channel AS "CHENEL", sub_channel AS "SUB-CHANEL",
       village AS "VILLAG", district AS "DISTRICT", province AS "PROVINCE"
FROM public.stores;
GRANT SELECT ON public.main_channels, public.mdes, public.outlet_directory TO authenticated;
GRANT INSERT, UPDATE, DELETE ON public.main_channels, public.mdes TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles, public.channels, public.sub_channels,
  public.stores, public.promotions, public.promotion_stores, public.follow_up_tasks,
  public.order_status_history TO authenticated;


-- 20261107010000_connected_app.sql
-- Real Auth profiles and atomic, RLS-enforced app persistence.

CREATE TABLE public.app_admin_allowlist (email TEXT PRIMARY KEY CHECK (email = lower(email)));
ALTER TABLE public.app_admin_allowlist ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.app_admin_allowlist FROM anon, authenticated;

CREATE FUNCTION public.ensure_my_profile() RETURNS public.profiles
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE account auth.users; result public.profiles; owner BOOLEAN;
BEGIN
  SELECT * INTO account FROM auth.users WHERE id = auth.uid();
  IF account.id IS NULL OR account.email_confirmed_at IS NULL THEN RAISE EXCEPTION 'A verified account is required'; END IF;
  owner := EXISTS (SELECT 1 FROM public.app_admin_allowlist WHERE email = lower(account.email));
    VALUES(account.id, account.email, CASE WHEN owner THEN 'Admin' ELSE split_part(account.email, '@', 1) END, CASE WHEN owner THEN 'admin' ELSE 'sales' END)
    ON CONFLICT(id) DO NOTHING;
  IF owner THEN UPDATE public.profiles SET role = 'admin', mde_id = NULL WHERE id = account.id; END IF;
  SELECT * INTO result FROM public.profiles WHERE id = account.id;
  RETURN result;
END; $$;
REVOKE ALL ON FUNCTION public.ensure_my_profile() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.ensure_my_profile() TO authenticated;
DROP POLICY profiles_select_policy ON public.profiles;
CREATE POLICY profiles_select_policy ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid() OR public.is_admin());

ALTER TABLE public.channels ADD COLUMN updated_at TIMESTAMPTZ NOT NULL DEFAULT now();
ALTER TABLE public.sub_channels ADD COLUMN updated_at TIMESTAMPTZ NOT NULL DEFAULT now();
ALTER TABLE public.promotions ADD COLUMN target_sub_channels TEXT[] NOT NULL DEFAULT '{}';
CREATE TRIGGER channels_updated_at BEFORE UPDATE ON public.channels FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();
CREATE TRIGGER sub_channels_updated_at BEFORE UPDATE ON public.sub_channels FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

CREATE TABLE public.new_products (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_name TEXT NOT NULL, sku TEXT NOT NULL,
  category TEXT NOT NULL, launch_date DATE NOT NULL, end_date DATE, pack_size TEXT NOT NULL,
  unit_price NUMERIC NOT NULL CHECK (unit_price >= 0), target_distribution_rate NUMERIC NOT NULL CHECK (target_distribution_rate BETWEEN 0 AND 100),
  target_units_per_store NUMERIC NOT NULL CHECK (target_units_per_store >= 0), description TEXT NOT NULL DEFAULT '',
  image_url TEXT, status TEXT NOT NULL CHECK (status IN ('Draft','Active','Completed','Cancelled')),
  target_sub_channels TEXT[] NOT NULL DEFAULT '{}', created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (end_date IS NULL OR end_date >= launch_date)
);
CREATE TABLE public.new_product_store_orders (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL REFERENCES public.new_products(id) ON DELETE CASCADE,
  store_id UUID NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
  order_status TEXT NOT NULL CHECK (order_status IN ('Ordered','Not Ordered','Sample Provided','Follow-up Required','Declined')),
  order_quantity NUMERIC, order_amount NUMERIC, order_date TIMESTAMPTZ, invoice_number TEXT,
  sample_given_date TIMESTAMPTZ, sample_qty NUMERIC, customer_feedback TEXT, next_follow_up_date TIMESTAMPTZ,
  updated_by UUID REFERENCES public.profiles(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(product_id, store_id)
);
CREATE TRIGGER new_products_updated_at BEFORE UPDATE ON public.new_products FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();
CREATE TRIGGER new_product_orders_updated_at BEFORE UPDATE ON public.new_product_store_orders FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();
ALTER TABLE public.new_products ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.new_product_store_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY new_products_read ON public.new_products FOR SELECT TO authenticated USING (public.is_admin() OR status IN ('Active','Completed'));
CREATE POLICY new_products_admin ON public.new_products FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY new_product_orders_read ON public.new_product_store_orders FOR SELECT TO authenticated USING (public.is_admin() OR public.is_store_assigned_to_me(store_id));
CREATE POLICY new_product_orders_admin ON public.new_product_store_orders FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY new_product_orders_update ON public.new_product_store_orders FOR UPDATE TO authenticated USING (public.is_store_assigned_to_me(store_id)) WITH CHECK (public.is_store_assigned_to_me(store_id));

CREATE FUNCTION public.prevent_order_reassignment() RETURNS trigger
LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  IF NOT public.is_admin() AND (
    NEW.store_id IS DISTINCT FROM OLD.store_id OR
    (to_jsonb(NEW)->>'promotion_id') IS DISTINCT FROM (to_jsonb(OLD)->>'promotion_id') OR
    (to_jsonb(NEW)->>'product_id') IS DISTINCT FROM (to_jsonb(OLD)->>'product_id')
  ) THEN RAISE EXCEPTION 'Only Admin may reassign an order'; END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER promotion_order_identity BEFORE UPDATE ON public.promotion_stores FOR EACH ROW EXECUTE FUNCTION public.prevent_order_reassignment();
CREATE TRIGGER new_product_order_identity BEFORE UPDATE ON public.new_product_store_orders FOR EACH ROW EXECUTE FUNCTION public.prevent_order_reassignment();

ALTER TABLE public.follow_up_tasks ALTER COLUMN assigned_user DROP NOT NULL,
  ADD COLUMN mde_id UUID REFERENCES public.mdes(id) ON DELETE RESTRICT,
  ADD CONSTRAINT task_assignee_present CHECK (assigned_user IS NOT NULL OR mde_id IS NOT NULL);
CREATE FUNCTION public.is_my_task(profile_id UUID, task_mde UUID) RETURNS BOOLEAN
LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public AS $$
 SELECT profile_id = auth.uid() OR EXISTS(SELECT 1 FROM public.profiles WHERE id = auth.uid() AND mde_id = task_mde);
$$;
DROP POLICY tasks_select_policy ON public.follow_up_tasks;
DROP POLICY tasks_insert_policy ON public.follow_up_tasks;
DROP POLICY tasks_update_policy ON public.follow_up_tasks;
DROP POLICY tasks_delete_policy ON public.follow_up_tasks;
CREATE POLICY tasks_select_policy ON public.follow_up_tasks FOR SELECT TO authenticated USING (public.is_admin() OR public.is_my_task(assigned_user,mde_id));
CREATE POLICY tasks_insert_policy ON public.follow_up_tasks FOR INSERT TO authenticated WITH CHECK (public.is_admin() OR (public.is_my_task(assigned_user,mde_id) AND public.is_store_assigned_to_me(store_id)));
CREATE POLICY tasks_update_policy ON public.follow_up_tasks FOR UPDATE TO authenticated USING (public.is_admin() OR public.is_my_task(assigned_user,mde_id)) WITH CHECK (public.is_admin() OR (public.is_my_task(assigned_user,mde_id) AND public.is_store_assigned_to_me(store_id)));
CREATE POLICY tasks_delete_policy ON public.follow_up_tasks FOR DELETE TO authenticated USING (public.is_admin() OR public.is_my_task(assigned_user,mde_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.new_products, public.new_product_store_orders TO authenticated;

CREATE FUNCTION public.app_apply_changes(changes JSONB) RETURNS JSONB
LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$
DECLARE op JSONB; target TEXT; payload JSONB; column_list TEXT; update_list TEXT; expected RECORD;
        actual_version TEXT; affected INTEGER; total INTEGER := 0; field TEXT; expected_count INTEGER; inserted INTEGER;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in is required'; END IF;
  IF jsonb_typeof(changes) <> 'array' OR jsonb_array_length(changes) > 24 THEN RAISE EXCEPTION 'Invalid change batch'; END IF;
  FOR op IN SELECT value FROM jsonb_array_elements(changes) LOOP
    target := op->>'table';
    IF target NOT IN ('profiles','channels','sub_channels','stores','promotions','promotion_stores','new_products','new_product_store_orders','follow_up_tasks','order_status_history') THEN RAISE EXCEPTION 'Unsupported table'; END IF;
    FOR expected IN SELECT key, value FROM jsonb_each_text(COALESCE(op->'expected', '{}'::jsonb)) LOOP
      EXECUTE format('SELECT to_jsonb(t)->>''updated_at'' FROM public.%I t WHERE id=$1 FOR UPDATE', target) INTO actual_version USING expected.key::uuid;
      IF actual_version IS NULL OR actual_version::timestamptz IS DISTINCT FROM expected.value::timestamptz THEN
        RAISE EXCEPTION 'This record changed on another device. Reload before retrying.' USING ERRCODE = '40001';
      END IF;
    END LOOP;
    IF op->>'operation' = 'delete' THEN
      payload := op->'ids';
      expected_count := jsonb_array_length(payload);
      EXECUTE format('DELETE FROM public.%I WHERE id IN (SELECT value::uuid FROM jsonb_array_elements_text($1))',target) USING payload;
    ELSIF op->>'operation' = 'upsert' THEN
      payload := op->'rows'; expected_count := jsonb_array_length(payload);
      IF expected_count = 0 OR expected_count > 2000 THEN RAISE EXCEPTION 'Invalid row count'; END IF;
      FOR field IN SELECT jsonb_object_keys(payload->0) LOOP
        IF field IN ('created_at','updated_at') OR NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=target AND column_name=field) THEN RAISE EXCEPTION 'Unsupported column'; END IF;
      END LOOP;
      IF NOT ((payload->0) ? 'id') THEN RAISE EXCEPTION 'An id is required'; END IF;
      SELECT string_agg(format('%I', key), ', ' ORDER BY key), string_agg(format('%I=source.%I',key,key), ', ' ORDER BY key) FILTER (WHERE key <> 'id')
        INTO column_list, update_list FROM jsonb_object_keys(payload->0) AS fields(key);
      IF update_list IS NULL THEN RAISE EXCEPTION 'No writable fields'; END IF;
      EXECUTE format('UPDATE public.%I AS dest SET %s FROM jsonb_populate_recordset(NULL::public.%I,$1) source WHERE dest.id=source.id',target,update_list,target) USING payload;
      GET DIAGNOSTICS affected = ROW_COUNT;
      EXECUTE format('INSERT INTO public.%I (%s) SELECT %s FROM jsonb_populate_recordset(NULL::public.%I,$1) source WHERE NOT EXISTS(SELECT 1 FROM public.%I dest WHERE dest.id=source.id)',target,column_list,column_list,target,target) USING payload;
      GET DIAGNOSTICS inserted = ROW_COUNT;
      IF affected + inserted <> expected_count THEN RAISE EXCEPTION 'Some records could not be saved with this account'; END IF;
      total := total + affected + inserted;
      CONTINUE;
    ELSE RAISE EXCEPTION 'Unsupported operation'; END IF;
    GET DIAGNOSTICS affected = ROW_COUNT;
    IF affected <> expected_count THEN RAISE EXCEPTION 'Some records could not be saved with this account'; END IF;
    total := total + affected;
  END LOOP;
  RETURN jsonb_build_object('applied',total);
END; $$;
REVOKE ALL ON FUNCTION public.app_apply_changes(JSONB) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.app_apply_changes(JSONB) TO authenticated;

